<section class="section container"><form method="get" action="<?= e(base_path().'/index.php') ?>" class="filters card"><input type="hidden" name="r" value="clubs"><label><span>Search clubs</span><input type="search" name="q" placeholder="Try technology, leadership, arts..." value="<?= e($search) ?>"></label><label><span>Category</span><select name="category"><option value="">All categories</option><?php foreach($categories as $cat): ?><option value="<?= e($cat['category']) ?>" <?= $category===$cat['category']?'selected':'' ?>><?= e($cat['category']) ?></option><?php endforeach; ?></select></label><label><span>Faculty</span><select name="faculty"><option value="">All faculties</option><?php foreach(faculty_options() as $f): ?><option value="<?= e($f) ?>" <?= $faculty===$f?'selected':'' ?>><?= e($f) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary" type="submit">Search</button></form><p class="result-count"><?= count($clubs) ?> clubs found</p><?php if($clubs): ?><div class="cards-grid club-grid"><?php foreach($clubs as $clubItem) require dirname(__DIR__).'/partials/club_card.php';?></div><?php else: ?><div class="empty-state">No clubs matched your filters. Try a broader search.</div><?php endif;?></section>
